def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The key encodes colors as connected groups of unit marks. The large
    # figure is built from the same-sized units, so recolor its rectangular
    # pieces according to the matching key-group size.
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    if not key:
        return out

    # Count connected same-color key groups.
    unseen = {(r, c) for r, c, _ in key}
    groups = []
    while unseen:
        r, c = next(iter(unseen))
        color = grid[r][c]
        stack = [(r, c)]
        unseen.remove((r, c))
        size = 0
        while stack:
            rr, cc = stack.pop()
            size += 1
            for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                if (nr,nc) in unseen and grid[nr][nc] == color:
                    unseen.remove((nr,nc))
                    stack.append((nr,nc))
        groups.append((size, color))
    groups.sort()

    # Figure is arranged in 2x2 units in these tasks. Find connected
    # rectangular patches on the unit lattice, then match patch area to key.
    unit = 2
    units = set()
    for r in range(0, h-unit+1, unit):
        for c in range(0, w-unit+1, unit):
            if all(grid[rr][cc] == 8 for rr in range(r,r+unit)
                                  for cc in range(c,c+unit)):
                units.add((r//unit, c//unit))

    # Separate the silhouette into maximal horizontal runs; their areas
    # determine the corresponding key component.
    runs = []
    for ur, uc in sorted(units):
        if (ur, uc) in {(r,c) for run in runs for r,c in run}:
            continue
        stack = [(ur,uc)]
        comp = {(ur,uc)}
        while stack:
            r,c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in units and q not in comp:
                    comp.add(q)
                    stack.append(q)
        runs.append(comp)

    # Assign each unit according to its area, with ties resolved in key order.
    for comp in runs:
        size = len(comp)
        _, color = min(groups, key=lambda g: (abs(g[0]-size), g[0]))
        for ur, uc in comp:
            for r in range(ur*unit, ur*unit+unit):
                for c in range(uc*unit, uc*unit+unit):
                    if grid[r][c] == 8:
                        out[r][c] = color
    return out
